// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    Caller caller;

    function setUp() public { c = new ModifierEntrancy(); caller = new Caller(address(c)); }

    function testFuzz_property(uint256 seed) public {
        vm.assume(seed >= 0); // wide: every seed is admissible; balance starts at zero
        bool ok;
        try caller.tryAirDrop() returns (bool r) { ok = r; } catch { ok = false; }
        // General rule: a caller with zero balance can always claim the airdrop (balance becomes 20).
        assertTrue(ok && c.tokenBalance(address(caller)) == 20);
    }
}

contract Caller {
    ModifierEntrancy immutable c;
    constructor(address target) { c = ModifierEntrancy(target); }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function tryAirDrop() external returns (bool) {
        c.airDrop();
        return true;
    }
}
